    model.addConstrs(x[i, i] == 0 for i in range(1, n + 1))  # cannot visit the same city twice
    model.addConstr(x[1, 1] == 0)  # start at city 1
    model.addConstr(x[1, j] == 0 for j in range(2, n + 1))  # cannot leave city 1 to visit another city
    model.addConstr(x[j, 1] == 0 for j in range(2, n + 1))  # cannot visit city 1 from another city

    # Set objective
    model.setObjective(quicksum(dist[i, j] * x[i, j] for i in range(1, n + 1) for j in range(1, n + 1)), GRB.MINIMIZE)

    # Optimize/solve the model
    model.optimize()

    # Return the optimized model
    return model
