    model.addConstrs(u[i] - u[j] + n * x[i, j] <= n - 1 for i in range(1, n + 1) for j in range(2, n + 1))  # subtour elimination
    model.addConstrs(x[i, i] == 0 for i in range(1, n + 1))  # cannot visit the same city twice
    model.addConstr(x[1, 1] == 0)  # start at city 1
    model.addConstr(x[1, j] == 0 for j in range(2, n + 1))  # cannot leave city 1 to visit another city
    model.addConstr(quicksum(x[j, 1] for j in range(2, n + 1)) == 1)  # must return to city 1

    # Set objective
    model.setObjective(quicksum(dist[i, j] * x[i, j] for i in range(1, n + 1) for j in range(1, n + 1)), GRB.MAXIMIZE)

    # Optimize/solve the model
    model.optimize()

    # Return the optimized model
    return model
